// Checkout conversion module - ensures paid events are recorded
const { logEvent } = require('./eventLogger');

async function processCheckout(session) {
  // Validate session
  if (!session || !session.cart || session.cart.length === 0) {
    logEvent('checkout_failed', { reason: 'empty_cart' });
    return { success: false, error: 'Cart is empty' };
  }
  // Simulate payment processing
  const paymentSuccess = await mockPaymentGateway(session);
  if (paymentSuccess) {
    logEvent('paid_event', { sessionId: session.id, amount: session.total });
    return { success: true, transactionId: 'txn_' + Date.now() };
  } else {
    logEvent('checkout_failed', { reason: 'payment_declined' });
    return { success: false, error: 'Payment declined' };
  }
}

async function mockPaymentGateway(session) {
  // Simulate network delay
  await new Promise(resolve => setTimeout(resolve, 100));
  // Always succeed for now (can be toggled via env)
  return process.env.MOCK_PAYMENT_SUCCESS !== 'false';
}

module.exports = { processCheckout };
